package org.example


fun leeNota(): Double {
    var nota: Double?

    println("Introduce una nota numérica entre 0 y 10: ")
    nota = readln().toDoubleOrNull()

    if (nota == null || nota !in 0.0..10.0) throw NumberFormatException("Nota no Valida")
    return nota
}

fun calificacion(nota: Double): String {

    return when (nota) {
        in 0.0..5.0 -> "Suspenso"
        in 5.1..7.0 -> "Aprobado"
        in 7.1..9.0 -> "Notable"
        in 9.1..10.0 -> "Sobresaliente"
        else -> ""
    }

}











